package uz.mirix.tracelens.internal;
import org.springframework.boot.web.reactive.function.client.WebClientCustomizer;import org.springframework.web.reactive.function.client.*;import reactor.core.publisher.Mono;import uz.mirix.tracelens.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class TraceLensWebClientCustomizer implements WebClientCustomizer {private final TraceLensProperties p;public TraceLensWebClientCustomizer(TraceLensProperties p){this.p=p;}public void customize(WebClient.Builder b){b.filter((request,next)->Mono.deferContextual(view->{TraceContext c=view.getOrDefault(TraceContextHolder.REACTOR_KEY,TraceContextHolder.current());if(c==null||!p.getHttpClient().isEnabled())return next.exchange(request);long started=System.nanoTime();AtomicReference<ClientResponse> response=new AtomicReference<>();AtomicReference<Throwable> failure=new AtomicReference<>();AtomicBoolean recorded=new AtomicBoolean();return next.exchange(request).doOnNext(response::set).doOnError(failure::set).doFinally(signal->{if(!recorded.compareAndSet(false,true))return;Map<String,String>a=new HashMap<>();if(response.get()!=null)a.put("status",Integer.toString(response.get().statusCode().value()));if(failure.get()!=null)a.put("error",failure.get().getClass().getSimpleName());c.record(TraceCategory.HTTP,HttpClientSupport.label(request.method().name(),request.url(),p),started,System.nanoTime(),a);});}));}}
